mapper.select:
select t.*
from (
    select f.*,
           row_number() over (
               partition by f.api
               order by (
                   cast(split_part(f.version, '.', 1) as bigint),
                   cast(split_part(f.version, '.', 2) as bigint),
                   cast(split_part(f.version, '.', 3) as bigint)
               ) desc
           ) as rn
    from ontology.function f


            and f.ontology_space_id = #{ontologySpaceId}


            and f.display_name like '%' || #{displayName} || '%'


            and f.type = #{type}


            and f.type not in

                #{et}



            and f.publish = #{publishStatus}


            and f.create_time >= cast(#{startDate} as timestamp)


            and f.create_time < cast(#{endDate} as date) + interval '1 day'


) t
where t.rn = 1
order by t.update_time desc nulls last, t.id desc

mapper.update:
update ontology.function set description = #{function.description}, reference_name = #{function.referenceName}, model = #{function.model}, code = #{function.code}, scan_status = #{function.scanStatus}, scan_result = #{function.scanResult, typeHandler=com.aircas.ptr.foundry.ontology.repository.handler.JsonbTypeHandler}, update_time = current_timestamp where id = #{function.id} and publish = 0
and update_time = #{originalUpdateTime}
and update_time is null

update ontology.function set publish = #{publish}, scan_status = #{scanStatus}, scan_result = #{scanResult, typeHandler=com.aircas.ptr.foundry.ontology.repository.handler.JsonbTypeHandler}, update_time = current_timestamp where id = #{id} and publish = 0
and update_time = #{originalUpdateTime}
and update_time is null
